package br.com.bora.entity; import jakarta.persistence.*; import lombok.*; @Entity @Getter @Setter public class Cliente{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public Long lojaId; public String nome; public String telefone; public String endereco; public String bairro; public String referencia; public java.math.BigDecimal totalGasto=java.math.BigDecimal.ZERO; public Integer qtdPedidos=0; public java.math.BigDecimal cashback=java.math.BigDecimal.ZERO; public java.time.OffsetDateTime ultimoPedido;}
